00096 //Controllo se la tessera selezionata può essere inserita sul campo
00097 bool is_match (elemento* tessere, int qty, int s, int d, int lato) {
00098     if (!lato && tessere[0].sinistra != d) return false;
00099     if (lato == 1) {
00100         int indice = 0;
00101         for(int i = 0; i < qty; i++) {
00102             if(tessere[i].sinistra == 0 && tessere[i].destra == 0) {
00103                 indice = i - 1;
00104                 break;
00105             }
00106         }
00107         if(tessere[indice].destra != s) return false;
00108     }
00109 
00110     return true;
00111 }
