00120             indice = i - 1;
00121             break;
00122         }
00123     }
00124 
00125     for(int i = 0; i < qty; i++) {
00126         if(tessere[i].sinistra && tessere[i].destra) {
00127             if(tessere[i].sinistra == campo[0].sinistra || tessere[i].destra == campo[0].sinistra) {
00128                 return true;
00129             }
00130                 
00131             if(tessere[i].sinistra == campo[indice].destra || tessere[i].destra == campo[indice].destra) {
00132                 return true;
00133             }
00134         }
00135             
00136     }
00137 
00138     return false;   
