00152 //Aggiorno le tessere
00153 void aggiorna_tessere (elemento* tessere, elemento* campo, int qty, int s, int d, int lato) {
00154     
00155     bool campo_vuoto = true;
00156     int indice_tes = 0;
00157     int indice_cam = 0;
00158 
00159     for(int i = 0; i < qty; i++) {
00160         if((tessere[i].sinistra == s && tessere[i].destra == d) || (tessere[i].sinistra == d && tessere[i].destra == s))
00161             indice_tes = i;
00162         if(campo[i].sinistra != 0 && campo[i].destra != 0) campo_vuoto = false;
00163     }
00164 
00165     if(campo_vuoto){
00166         campo[0].sinistra = s;
00167         campo[0].destra = d;
00168         tessere[indice_tes].sinistra = 0;
00169         tessere[indice_tes].destra = 0;
00170     } else {
00171         if(lato) {
00172             for(int i = 0; i < qty; i++) {
00173                 if(campo[i].sinistra == 0 && campo[i].destra == 0) {
00174                     indice_cam = i;
00175                     break;
00176                 }
00177             }
00178             campo[indice_cam].sinistra = s;
00179             campo[indice_cam].destra = d;
00180             tessere[indice_tes].sinistra = 0;
00181             tessere[indice_tes].destra = 0;
00182 
00183         } else {
00184             for(int i = qty - 1; i != 0; i--) {
00185                 campo[i] = campo[i - 1];
00186             }
00187             campo[0].sinistra = s;
00188             campo[0].destra = d;
00189             tessere[indice_tes].sinistra = 0;
00190             tessere[indice_tes].destra = 0;
00191         }
00192     }
00193 }
