00195 //Calcolo punteggio finale
00196 int calcolo_punteggio (elemento* tessere, int qty) {
00197     if(qty == 0) return 0;
00198     return tessere[0].sinistra + tessere[0].destra + calcolo_punteggio(tessere+1,qty-1);
00199 }
