00201 //Cerco migliore combinazione ricorsione
00202 int best_comb_rec (elemento* tessere,elemento* campo, int qty,int camp_qty, int act_sum, int ind_tex, int mode) {
00203     
00204     int sum = 0;
00205 
00206     if(mode == 1) {
00207         printf("\n#####################\n");
00208         printf("\nTESSERE A DISPOSIZIONE: ");
00209         stampa_tessere(tessere, qty);
00210         printf("\nCAMPO: ");
00211         stampa_tessere(campo, qty);
00212         printf("\n#####################\n");
00213     }
00214 
00215     if(ind_tex == qty) return sum;
00216 
00217     if(qty == camp_qty) return sum;     
00218     
00219     
00220     for(int i = 0; i < qty; i++) {
00221         if(is_match(campo,qty,tessere[i].sinistra,tessere[i].destra, 0) && i != ind_tex && !is_null(tessere,i)) {
00222             aggiorna_tessere(tessere,campo,qty,tessere[i].sinistra,tessere[i].destra,0);
00223             sum = tessere[i].sinistra + tessere[i].destra + best_comb_rec(tessere,campo,qty,camp_qty+1,act_sum,i,mode);
00224         }
00225 
00226         if(is_match(campo,qty,tessere[i].destra,tessere[i].sinistra, 0) && i != ind_tex && !is_null(tessere,i)) {
00227             aggiorna_tessere(tessere,campo,qty,tessere[i].destra,tessere[i].sinistra,0);
00228             sum = tessere[i].sinistra + tessere[i].destra + best_comb_rec(tessere,campo,qty,camp_qty+1,act_sum,i,mode);
00229         }
00230 
00231         if(is_match(campo,qty,tessere[i].sinistra,tessere[i].destra, 1) && i != ind_tex && !is_null(tessere,i)) {
00232             aggiorna_tessere(tessere,campo,qty,tessere[i].sinistra,tessere[i].destra,1);
00233             sum = tessere[i].sinistra + tessere[i].destra + best_comb_rec(tessere,campo,qty,camp_qty+1,act_sum,i,mode);
00234         }
00235 
00236         if(is_match(campo,qty,tessere[i].destra,tessere[i].sinistra, 1) && i != ind_tex && !is_null(tessere,i)) {
00237             aggiorna_tessere(tessere,campo,qty,tessere[i].destra,tessere[i].sinistra,1);
00238             sum = tessere[i].sinistra + tessere[i].destra + best_comb_rec(tessere,campo,qty,camp_qty+1,act_sum,i,mode);
00239         }
00240     }
00241 }
