00243 //Cerco migliore combinazione 
00244 int best_comb (elemento* tessere,elemento* campo, int qty,elemento* tessere_rim, int* s, int* d, int* ind) {
00245 
00246     int sum = 0;
00247 
00248     elemento*tessere_copy = (elemento*) malloc(sizeof(elemento)*qty);
00249     if(!tessere_copy) exit(EXIT_FAILURE);
00250 
00251     for(int i = 0; i < qty; i++) {
00252         tessere_copy[i] = tessere[i];
00253     }
00254 
00255     for(int i = 0; i < qty; i++) {
00256 
00257         //printf("\n***************\n HO INIZIATO CON [%d|%d]\n*****************\n",tessere[i].sinistra, tessere[i].destra );
00258 
00259         elemento* campo_prova = (elemento*) malloc(sizeof(elemento)*qty);
00260         if(!campo_prova) exit(EXIT_FAILURE);
00261 
00262         for(int j = 0; j < qty; j++) {
00263             campo_prova[j].sinistra = 0;
00264             campo_prova[j].destra = 0;
00265         }
00266 
00267         campo_prova[0] = tessere_copy[i];
00268         tessere_copy[i].sinistra = 0;
00269         tessere_copy[i].destra = 0;
00270 
00271         best_comb_rec(tessere_copy,campo_prova,qty, 1, 0, i, 0);
00272         int punti = calcolo_punteggio(campo_prova,qty);
00273 
00274         if(punti > sum) {
00275             //printf("\n***************\n IL VINCENTE E' [%d|%d]\n*****************\n",tessere[i].sinistra, tessere[i].destra );
00276             *ind = i;
00277             *s = tessere[i].sinistra;
00278             *d = tessere[i].destra;
00279             sum = punti;
00280             for(int j = 0; j < qty; j++) 
00281                 tessere_rim[j] = tessere_copy[j];
00282             for(int i = 0; i < qty; i++)
00283                 campo[i] = campo_prova[i];
00284         }
00285 
00286         for(int j = 0; j < qty; j++)
00287             tessere_copy[j] = tessere[j];
00288 
00289         for(int k = 0; k < qty; k++) {
00290             campo_prova[k].sinistra = 0;
00291             campo_prova[k].destra = 0;
00292         }
00293             
00294 
00295         free(campo_prova);
00296         
00297     }
00298 
00299     free(tessere_copy);
00300     return sum;
00301 }
