00375 
00376         scanf("%s", mystr_tessera);
00377 
00378         s = mystr_tessera[0] - '0';
00379         d = mystr_tessera[1] - '0';
00380         free(mystr_tessera);
00381 
00382         if(s < 1 || s > 6 || d < 1 || d > 6) {
00383             printf("\nInserimento non valido! Riprovare.\n");
00384             s = 0;
00385             d = 0;
00386             continue;
00387         }
00388 
00389         if(ricerca_tessera(tessere, qty, s, d)) {
00390             if(campo[0].sinistra && campo[0].destra) {
00391                 printf("\nIn quale lato la vuoi inserire?\nA = Sinistra\nD = Destra\n\n0 = Annulla\n");
