00398 
00399                 lato_app = (int)lato_str[0];
00400                 free(lato_str);
00401 
00402                 if (lato_app==97 || lato_app==65) lato = 0; // 97=a 65=A
00403                 if (lato_app==100 || lato_app ==68) lato = 1; // 100=d 68=D
00404                 if (lato_app == 48) lato = 3; // 48 = zero
00405 
00406                 if(lato != 0 && lato != 1 && lato != 3) {
00407                     lato = -1;
00408                     printf("\nSelezione lato errata!\n");
00409                     continue;
00410                 }
00411             }
00412 
00413             if(!is_void(campo,qty) && lato != 0 && lato != 1 && lato != 3) {
00414                 printf("\nSelezione lato errata!\n");
00415                 continue;
00416             }
00417 
00418             if(lato == 3) continue;
00419 
00420             if(!is_void(campo,qty) && !is_match(campo,qty,s,d,lato) ) {
00421                 printf("\n!!!!!!!!!!!!!!!!!\n");
00422                 printf("Mossa non valida!\n");
00423                 printf("!!!!!!!!!!!!!!!!!\n");
00424                 continue;
00425             }
00426 
00427             aggiorna_tessere(tessere,campo, qty, s, d, lato);
00428         } else {
00429             printf("\n\nTessera non esistente!\n");
00430         }
00431         
00432         if(is_void(tessere, qty) || !continue_game(tessere,campo,qty)) gameStatus = FINISH;
00433     
00434     }
00435 }
